    private void NavigateToPetEditView()
    {
        _fx.ClickById("btn-new-owner");
        _fx.TypeInto("txt-owner-name", "R6測試飼主");
        _fx.TypeInto("txt-owner-national-id", "R6123456789");
        _fx.TypeInto("txt-owner-phone", "0912222222");
