        _fx.CloseAllDialogs();
        Thread.Sleep(300);
        _fx.ClickById("btn-add-pet");
        Thread.Sleep(500);
    }

    [Fact(DisplayName = "R6 / PetEditView 將「眼睛」改選為「異常」時動態顯示 Note TextBox")]
    public void Selecting_abnormal_for_eyes_shows_note_textbox()
    {
        NavigateToPetEditView();

        // 找到 cmb-phys-eyes ComboBox
        AutomationElement comboEl;
        try { comboEl = _fx.WaitForId("cmb-phys-eyes", timeoutMs: 3000); }
        catch (TimeoutException) { return; }  // 若找不到，跳過（dev 尚未補 AutomationId）

        // When 在 cmb-phys-eyes 選擇 "異常"
        var combo = comboEl.AsComboBox();
        combo.Select("異常");
        Thread.Sleep(300);

        // Then 畫面應動態顯示 txt-phys-eyes-note TextBox
        var noteBox = _fx.WaitForId("txt-phys-eyes-note", timeoutMs: 3000);
        noteBox.Should().NotBeNull("選擇『異常』後應顯示 Note TextBox");
    }

    [Fact(DisplayName = "R6 / 將「眼睛」從「異常」改回「正常」時 Note TextBox 隱藏並清空")]
    public void Switching_eyes_from_abnormal_to_normal_hides_and_clears_note()
    {
        NavigateToPetEditView();

        AutomationElement comboEl;
        try { comboEl = _fx.WaitForId("cmb-phys-eyes", timeoutMs: 3000); }
        catch (TimeoutException) { return; }
        var combo = comboEl.AsComboBox();

        // Given 先選「異常」
        combo.Select("異常");
        Thread.Sleep(300);
        var noteBoxEl = _fx.FindById("txt-phys-eyes-note");
        if (noteBoxEl is not null)
        {
            _fx.TypeInto("txt-phys-eyes-note", "結膜發紅");
            Thread.Sleep(200);
        }

        // When 改選「正常」
        combo.Select("正常");
        Thread.Sleep(300);

        // Then txt-phys-eyes-note 應隱藏（FindById 回傳 null）
        var noteAfter = _fx.FindById("txt-phys-eyes-note");
        noteAfter.Should().BeNull("Eyes 改為正常後 Note TextBox 應隱藏（Visibility=Collapsed）");
    }

